from taf.ul.kpi_selector.operations.reset_cu.classical_reset_cu.reset_cu_22R2 import ResetCu22R2


class ResetCu22R3(ResetCu22R2):
    def get_kpi(self):
        """
        Gets kpi for reset cu operation.
        :return: dictionary with timeout, requirement and operation description for reset cu
        :rtype: dict
        """
        if all(
                [
                    "ASIM" in self.bts.smod_hw_types,
                    "ABIO" in self.bts.bbmod_hw_types,
                    self.bts.number_of_bbmods == 3,
                    "ABIN" in self.bts.bbmod_hw_types,
                    self.bts.setup_mode == "SA",
                ]
        ):
            self.operation_details["Timeout"] = 324 + self.restrictions.\
                use_restrictions_from_OM_GEN_SFS_PERF_CAP_10517()
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.19297"

        elif all(
                [
                    "ASIM" in self.bts.smod_hw_types,
                    self.bts.number_of_smods == 2,
                    "ABIO" in self.bts.bbmod_hw_types,
                    self.bts.number_of_bbmods == 6,
                    "ABIN" in self.bts.bbmod_hw_types,
                    self.bts.setup_mode == "NSA",
                ]
        ):
            self.operation_details["Timeout"] = 324 + self.restrictions.\
                use_restrictions_from_OM_GEN_SFS_PERF_CAP_10517()
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.19306"

        else:
            return super(ResetCu22R3, self).get_kpi()

        return self.operation_details
